package plumbing_test

import (
	"context"
	"encoding/json"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"runtime"
	"strconv"
	"strings"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/plumbing"
	"github.com/gitdek/invariant/internal/synth"
	"github.com/gitdek/invariant/internal/toolchain"
)

// TestSandboxBudgetAndRealCheckout pins #397's public limits: eight global
// queue workers, a ten-minute touched-test phase and a twelve-minute whole
// Sandbox.Run deadline, including staging, startup, vet and acceptance tests.
// Sandbox.Timeout and Sandbox.ShardTimeout may shorten their defaults, never
// extend them. A separate minute for startup and fifteen seconds for cleanup
// conservatively reserve more time before either backend's unchanged limit.
//
// The merger runs the full checkout in two waves: two simultaneous cold-cache
// runs must pass, then three simultaneous fresh-cache runs must return results
// within the budget, with partial results allowed. Both waves measure peaks:
//
//	INVARIANT_PLUMBING_REAL=1 go test ./internal/plumbing -run '^TestSandboxBudgetAndRealCheckout$' -count=1 -timeout 45m
//
// Image acquisition is outside the timed runs, as it is when the watcher starts.
// Only this subtest's plan touches internal/verify: this acceptance file belongs
// to plumbing so #397 can itself be built by the old, unsharded sandbox.
// The real-image check records kernel cgroup high-water marks on normal exit
// or just before forced removal, including compilation's peaks. Host report
// files survive cancellation of the run's Docker CLI and output pipe.
// The sandbox does not forward INVARIANT_PLUMBING_REAL into its container, so
// this same acceptance test runs its default assertions there without nesting
// more Docker runs. The default assertions always run, even without Docker.
func TestSandboxBudgetAndRealCheckout(t *testing.T) {
	for _, limit := range []struct {
		name string
		got  time.Duration
		want time.Duration
	}{
		{"whole run", plumbing.SandboxTimeout, 12 * time.Minute},
		{"touched-test phase", plumbing.SandboxShardTimeout, 10 * time.Minute},
		{"startup reserve", plumbing.SandboxStartupAllowance, time.Minute},
		{"cleanup reserve", plumbing.SandboxCleanupAllowance, 15 * time.Second},
	} {
		if limit.got != limit.want {
			t.Errorf("%s limit = %s, want %s", limit.name, limit.got, limit.want)
		}
	}
	if plumbing.SandboxShards != 8 {
		t.Errorf("sandbox shard workers = %d, want 8", plumbing.SandboxShards)
	}
	budget := plumbing.SandboxTimeout + plumbing.SandboxStartupAllowance + plumbing.SandboxCleanupAllowance
	limits := make(map[string]time.Duration)
	for _, name := range []string{"codex", "claude-code"} {
		limit := sandboxBudgetBackendLimit(t, name)
		limits[name] = limit
		if limit != 900*time.Second {
			t.Errorf("%s emitted tool limit %s, want the unchanged 900s limit", name, limit)
		}
		if budget >= limit {
			t.Errorf("sandbox deadline plus startup and cleanup reserves = %s, must be below %s's emitted %s tool limit", budget, name, limit)
		}
	}
	if t.Failed() {
		t.FailNow()
	}

	t.Run("real_image", func(t *testing.T) {
		if os.Getenv("INVARIANT_PLUMBING_REAL") != "1" {
			// A SKIP line for this subtest is misread as a skipped parent by
			// the old sandbox parser that checks this change.
			return
		}
		_, file, _, ok := runtime.Caller(0)
		if !ok {
			t.Fatal("cannot locate this checkout's acceptance test")
		}
		root := filepath.Clean(filepath.Join(filepath.Dir(file), "..", ".."))
		const acceptanceFile = "internal/plumbing/sandbox_budget_accept_test.go"
		source, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(acceptanceFile)))
		if err != nil {
			t.Fatal(err)
		}
		plan := &plumbing.Plan{
			Name:    "Exercise the whole slow package inside the tool budget",
			Summary: "Run the touched plumbing and verify packages, vet and this pinned acceptance test with two, then three simultaneous cold-cache sandboxes.",
			Files:   []string{"internal/plumbing/sandbox.go", "internal/verify/verify.go"},
			Tests: []plumbing.Test{{
				Name: "TestSandboxBudgetAndRealCheckout", File: acceptanceFile,
				Says: "Two simultaneous checks pass before the sandbox deadline; three simultaneous checks return within the budget, with measured memory and process peaks below their enforced limits.",
			}},
			Sources: map[string]string{acceptanceFile: string(source)},
		}
		if err := plan.Validate(); err != nil {
			t.Fatal(err)
		}
		setupCtx, finishSetup := context.WithTimeout(context.Background(), 8*time.Minute)
		defer finishSetup()
		image, err := toolchain.PlumbingImage(setupCtx)
		if err != nil {
			t.Fatalf("acquire the real pinned sandbox image: %v", err)
		}
		modCmd := exec.CommandContext(setupCtx, "go", "env", "GOMODCACHE")
		modCmd.Dir = root
		mod, err := modCmd.Output()
		if err != nil || strings.TrimSpace(string(mod)) == "" {
			t.Fatalf("find the real Go module cache: %v; output %q", err, mod)
		}
		finishSetup()
		reports := sandboxBudgetObserveResources(t)
		seenReports := make(map[string]bool)

		type outcome struct {
			i       int
			result  plumbing.Result
			err     error
			elapsed time.Duration
		}
		for _, wave := range []struct {
			runs     int
			mustPass bool
		}{{2, true}, {3, false}} {
			sandboxes := make([]plumbing.Sandbox, wave.runs)
			for i := range sandboxes {
				sandboxes[i] = plumbing.Sandbox{
					Image: image, ModCache: strings.TrimSpace(string(mod)),
					Cache: filepath.Join(t.TempDir(), "cold-cache"), Original: root,
				}
			}
			t.Logf("running %d concurrent cold-cache containers, each with 8 global queue workers, 4 GiB and 1024 PIDs: aggregate caps %d GiB and %d PIDs; sandbox deadline %s, outer budget %s", wave.runs, wave.runs*4, wave.runs*1024, plumbing.SandboxTimeout, budget)
			ctx, cancel := context.WithTimeout(context.Background(), budget)
			ready := make(chan struct{}, wave.runs)
			start := make(chan struct{})
			done := make(chan outcome, wave.runs)
			for i, sb := range sandboxes {
				go func() {
					ready <- struct{}{}
					<-start
					began := time.Now()
					result, err := sb.Run(ctx, root, plan)
					done <- outcome{i: i, result: result, err: err, elapsed: time.Since(began)}
				}()
			}
			for range wave.runs {
				<-ready
			}
			began := time.Now()
			close(start)
			for range wave.runs {
				var out outcome
				select {
				case out = <-done:
				case <-ctx.Done():
					cancel()
					t.Fatalf("%d concurrent real sandbox runs did not all return within %s", wave.runs, budget)
				}
				t.Logf("%d-run wave: real sandbox %d finished in %s", wave.runs, out.i+1, out.elapsed)
				if out.err != nil {
					t.Errorf("%d-run wave: real sandbox %d did not return a usable result after %s: %v\n%s\n%s", wave.runs, out.i+1, out.elapsed, out.err, out.result.Summary(), out.result.Tail(16000))
				}
				if wave.mustPass {
					if !out.result.Passed() {
						t.Errorf("%d-run wave: real sandbox %d failed after %s:\n%s\n%s", wave.runs, out.i+1, out.elapsed, out.result.Summary(), out.result.Tail(16000))
					}
					if out.elapsed >= plumbing.SandboxTimeout {
						t.Errorf("%d-run wave: real sandbox %d took %s, want less than its %s deadline", wave.runs, out.i+1, out.elapsed, plumbing.SandboxTimeout)
					}
					if !out.result.Accepted[acceptanceFile+":TestSandboxBudgetAndRealCheckout"] {
						t.Errorf("%d-run wave: real sandbox %d did not pass the pinned acceptance test in internal/plumbing", wave.runs, out.i+1)
					}
				} else if !out.result.Passed() {
					// Overload may exhaust the deadline, but must return the
					// work already completed and name unfinished or failed work.
					passed, unfinished := false, false
					summary := out.result.Summary()
					for _, result := range out.result.TestResults {
						if result.Status == "passed" {
							passed = true
						}
						if result.Status == "failed" || result.Status == "running" || result.Status == "not_run" {
							unfinished = true
							if result.Package == "" || result.Name == "" || !strings.Contains(summary, result.Package) || !strings.Contains(summary, result.Name) {
								t.Errorf("three-run wave: real sandbox %d did not name partial result %+v in its summary:\n%s", out.i+1, result, summary)
							}
						}
					}
					if !passed || !unfinished {
						t.Errorf("three-run wave: real sandbox %d returned failure without completed and unfinished/failed test results: %+v\n%s\n%s", out.i+1, out.result.TestResults, summary, out.result.Tail(16000))
					}
				}
				if out.elapsed >= budget {
					t.Errorf("%d-run wave: real sandbox %d took %s, outside its %s return budget", wave.runs, out.i+1, out.elapsed, budget)
				}
				for name, limit := range limits {
					if out.elapsed >= limit {
						t.Errorf("%d-run wave: real sandbox %d took %s, outside %s's %s tool limit", wave.runs, out.i+1, out.elapsed, name, limit)
					}
				}
			}
			elapsed := time.Since(began)
			cancel()
			t.Logf("all %d real sandbox runs completed in %s", wave.runs, elapsed)
			if elapsed >= budget || wave.mustPass && elapsed >= plumbing.SandboxTimeout {
				t.Errorf("%d concurrent sandbox runs took %s, exceeding the required deadline/budget", wave.runs, elapsed)
			}
			entries, err := os.ReadDir(reports)
			if err != nil {
				t.Fatal("read the real-image resource reports: ", err)
			}
			var fresh []string
			for _, entry := range entries {
				if strings.HasSuffix(entry.Name(), ".json") && !seenReports[entry.Name()] {
					seenReports[entry.Name()] = true
					fresh = append(fresh, entry.Name())
				}
			}
			if len(fresh) != wave.runs {
				t.Errorf("%d-run wave produced %d container resource reports, want %d", wave.runs, len(fresh), wave.runs)
			}
			for i, name := range fresh {
				data, err := os.ReadFile(filepath.Join(reports, name))
				if err != nil {
					t.Error("read resource report: ", err)
					continue
				}
				t.Logf("%d-run wave: resource report %d is for container %s", wave.runs, i+1, strings.TrimSuffix(name, ".json"))
				sandboxBudgetCheckResources(t, i+1, "@@s397-resources "+string(data))
			}
		}
	})
}

// Wrap the real Docker CLI to read kernel-maintained peaks on normal exit and
// immediately before forced removal. A cidfile identifies each container; host
// report files survive loss of the run's output pipe on cancellation. No test
// commands, limits or mounts are replaced. The extra inspection/exec calls are
// bounded and never prevent delegation of the original removal command.
// A polling docker-stats sample can miss compilation peaks; memory.peak and
// pids.peak include every process since container creation. Missing counters or
// observer failures fail only the opt-in check. It needs a cgroup-v2 Docker host.
func sandboxBudgetObserveResources(t *testing.T) string {
	t.Helper()
	docker, err := exec.LookPath("docker")
	if err != nil {
		t.Fatal(err)
	}
	docker, err = filepath.Abs(docker)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := exec.LookPath("python3"); err != nil {
		t.Fatal("the real-image resource observer needs python3 on the host: ", err)
	}
	dir := t.TempDir()
	if err := os.WriteFile(filepath.Join(dir, "docker"), []byte(sandboxBudgetDocker), 0o755); err != nil {
		t.Fatal(err)
	}
	reports := filepath.Join(dir, "reports")
	if err := os.MkdirAll(reports, 0o700); err != nil {
		t.Fatal(err)
	}
	t.Setenv("S397_REAL_DOCKER", docker)
	t.Setenv("S397_RESOURCE_DIR", dir)
	t.Setenv("PATH", dir+string(os.PathListSeparator)+os.Getenv("PATH"))
	return reports
}

func sandboxBudgetCheckResources(t *testing.T, run int, output string) {
	t.Helper()
	const marker = "@@s397-resources "
	var reports []string
	for _, line := range strings.Split(output, "\n") {
		if strings.HasPrefix(line, marker) {
			reports = append(reports, strings.TrimPrefix(line, marker))
		}
	}
	if len(reports) != 1 {
		t.Errorf("real sandbox %d has %d resource reports, want one measured report", run, len(reports))
		return
	}
	var usage struct {
		MemoryPeak  int64  `json:"memory_peak"`
		MemoryLimit int64  `json:"memory_limit"`
		PIDsPeak    int64  `json:"pids_peak"`
		PIDsLimit   int64  `json:"pids_limit"`
		OOMs        int64  `json:"oom"`
		OOMKills    int64  `json:"oom_kill"`
		PIDsDenied  int64  `json:"pids_denied"`
		Error       string `json:"error"`
	}
	if err := json.Unmarshal([]byte(reports[0]), &usage); err != nil || usage.Error != "" {
		t.Errorf("real sandbox %d could not measure resource peaks: %v; %s", run, err, reports[0])
		return
	}
	t.Logf("real sandbox %d: peak memory %d / %d bytes, peak processes %d / %d, OOM events %d, OOM kills %d, denied processes %d", run, usage.MemoryPeak, usage.MemoryLimit, usage.PIDsPeak, usage.PIDsLimit, usage.OOMs, usage.OOMKills, usage.PIDsDenied)
	if usage.MemoryLimit != 4*1024*1024*1024 || usage.PIDsLimit != 1024 {
		t.Errorf("real sandbox %d did not enforce 4 GiB and 1024 PIDs: %+v", run, usage)
	}
	if usage.MemoryPeak <= 0 || usage.MemoryPeak >= usage.MemoryLimit || usage.PIDsPeak <= 0 || usage.PIDsPeak >= usage.PIDsLimit {
		t.Errorf("real sandbox %d did not stay below its memory/process caps: %+v", run, usage)
	}
	if usage.OOMs != 0 || usage.OOMKills != 0 || usage.PIDsDenied != 0 {
		t.Errorf("real sandbox %d hit a memory/process limit: %+v", run, usage)
	}
}

const sandboxBudgetDocker = `#!/usr/bin/env python3
import fcntl, json, os, pathlib, re, selectors, shlex, subprocess, sys, time, uuid
args = sys.argv[1:]
real = os.environ["S397_REAL_DOCKER"]
root = pathlib.Path(os.environ["S397_RESOURCE_DIR"])
reports = root / "reports"
marker = b"@@s397-resources "
probe = '''import json, pathlib
root = pathlib.Path("/sys/fs/cgroup")
def counter(name):
    return int((root / name).read_text().strip())
def events(name):
    return {key: int(value) for key, value in (line.split() for line in (root / name).read_text().splitlines())}
try:
    memory = events("memory.events")
    pids = events("pids.events")
    report = dict(memory_peak=counter("memory.peak"), memory_limit=counter("memory.max"),
                  pids_peak=counter("pids.peak"), pids_limit=counter("pids.max"),
                  oom=memory["oom"], oom_kill=memory["oom_kill"], pids_denied=pids["max"])
except Exception as error:
    report = dict(error=str(error))
print("\\n@@s397-resources " + json.dumps(report), flush=True)
'''
def atomic(path, value):
    tmp = path.with_name(path.name + "." + uuid.uuid4().hex + ".tmp")
    tmp.write_text(json.dumps(value))
    os.replace(tmp, path)
def save(cid, report):
    if not re.fullmatch("[0-9a-f]{64}", cid):
        unknown = cid
        cid = "observer-error-" + uuid.uuid4().hex
        report = dict(error="cannot identify observed container: " + repr(unknown), detail=report)
    path = reports / (cid + ".json")
    with (reports / (cid + ".lock")).open("a") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        if path.exists():
            prior = json.loads(path.read_text())
            if not prior.get("error"):
                if report.get("error"):
                    return # An already recorded natural exit can race rm.
                for key in ("memory_peak", "pids_peak", "oom", "oom_kill", "pids_denied"):
                    report[key] = max(prior[key], report[key])
                if any(prior[key] != report[key] for key in ("memory_limit", "pids_limit")):
                    report["error"] = "container limits changed between observations"
        atomic(path, report)
def read_cid(path):
    try: return pathlib.Path(path).read_text().strip()
    except FileNotFoundError: return ""
def value(flag):
    for i, arg in enumerate(args):
        if arg == flag and i+1 < len(args): return args[i+1]
        if arg.startswith(flag + "="): return arg[len(flag)+1:]
    return ""
def resolve(ref):
    if re.fullmatch("[0-9a-f]{64}", ref): return ref
    for path in root.glob("run-*.json"):
        run = json.loads(path.read_text())
        cid = run.get("cid") or read_cid(run["cidfile"])
        if cid and (ref == run["name"] or cid.startswith(ref)): return cid
    result = subprocess.run([real, "inspect", "--format", "{{.Id}}", ref],
                            capture_output=True, text=True, timeout=2)
    if result.returncode: raise RuntimeError(result.stderr.strip())
    return result.stdout.strip()
def extract(data):
    for line in data.splitlines():
        if line.startswith(marker): return json.loads(line[len(marker):])
    raise RuntimeError("container did not emit a cgroup resource report")
if args and args[0] == "rm":
    try:
        for ref in (arg for arg in args[1:] if not arg.startswith("-")):
            cid = ""
            try:
                cid = resolve(ref)
                prior = reports / (cid + ".json")
                if prior.exists() and not json.loads(prior.read_text()).get("error"): continue
                result = subprocess.run([real, "exec", cid, "python3", "-c", probe],
                                        capture_output=True, timeout=3)
                if result.returncode: raise RuntimeError(result.stderr.decode(errors="replace").strip())
                save(cid, extract(result.stdout))
            except Exception as error:
                save(cid, dict(error="before removal of " + ref + ": " + str(error)))
    finally:
        os.execv(real, [real, *args])
if args and args[0] == "run":
    if args[-3:-1] != ["sh", "-c"]:
        sys.exit("sandbox resource observer expected the sandbox's sh -c entry")
    cidfile = value("--cidfile")
    if not cidfile:
        cidfile = str(root / ("cid-" + uuid.uuid4().hex))
        args[1:1] = ["--cidfile", cidfile]
    registration = root / ("run-" + uuid.uuid4().hex + ".json")
    identity = dict(cidfile=cidfile, name=value("--name"))
    atomic(registration, identity)
    args[-1] = "sh -c " + shlex.quote(args[-1]) + "\ns397_status=$?\npython3 -c " + shlex.quote(probe) + '\nexit "$s397_status"\n'
    process = subprocess.Popen([real, *args], stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    pending = b""
    selector = selectors.DefaultSelector()
    selector.register(process.stdout, selectors.EVENT_READ)
    end = time.monotonic() + 810
    try:
        while selector.get_map():
            if time.monotonic() >= end: raise TimeoutError("resource observer's Docker run exceeded 810 seconds")
            if not identity.get("cid") and read_cid(cidfile):
                identity["cid"] = read_cid(cidfile)
                atomic(registration, identity)
            for key, _ in selector.select(timeout=max(0, min(1, end-time.monotonic()))):
                chunk = os.read(key.fd, 65536)
                if not chunk:
                    selector.unregister(key.fileobj)
                    continue
                pending += chunk
                while b"\n" in pending:
                    line, pending = pending.split(b"\n", 1)
                    if line.startswith(marker): save(read_cid(cidfile), json.loads(line[len(marker):]))
                sys.stdout.buffer.write(chunk)
                sys.stdout.buffer.flush()
        code = process.wait(timeout=2)
    except Exception as error:
        save(read_cid(cidfile), dict(error=str(error)))
        process.kill()
        try: process.wait(timeout=2)
        except subprocess.TimeoutExpired: pass
        code = 1
    finally:
        selector.close()
    sys.exit(code if code >= 0 else 128-code)
os.execv(real, [real, *args])
`

// Exercise each production Backend.Run rather than copying its defaults into
// the assertion. Only the CLI process is replaced; it records the arguments or
// single timeout environment variable the real backend actually supplied.
func sandboxBudgetBackendLimit(t *testing.T, name string) time.Duration {
	t.Helper()
	dir := t.TempDir()
	const standIn = `#!/bin/sh
set -eu
here=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
printf '%s\n' "$@" > "$here/args"
printf '%s\n' "${MCP_TOOL_TIMEOUT-}" > "$here/tool-timeout"
cat "$here/events"
`
	events := "{\"type\":\"thread.started\",\"thread_id\":\"sandbox-budget\"}\n" +
		"{\"type\":\"turn.started\"}\n" +
		"{\"type\":\"turn.completed\",\"usage\":{\"input_tokens\":1,\"output_tokens\":1}}\n"
	if name == "claude-code" {
		events = "{\"type\":\"result\",\"subtype\":\"success\",\"result\":\"Done.\",\"total_cost_usd\":0,\"num_turns\":1}\n"
	}
	for file, data := range map[string]string{"agent": standIn, "events": events} {
		if err := os.WriteFile(filepath.Join(dir, file), []byte(data), 0o700); err != nil {
			t.Fatal(err)
		}
	}
	var backend synth.Backend
	switch name {
	case "codex":
		backend = synth.Codex{Binary: filepath.Join(dir, "agent"), Home: filepath.Join(dir, "home"), MaxTurns: 5}
	case "claude-code":
		backend = synth.ClaudeCode{Binary: filepath.Join(dir, "agent"), MaxTurns: 5, BudgetUSD: 1}
	default:
		t.Fatalf("unhandled agent backend %q", name)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	usage, err := backend.Run(ctx, synth.Job{
		Workspace: t.TempDir(), Prompt: "Record the test tool's configured limit.",
		GateServer: []string{"invariant", "mcp", "-plumbing"}, Tools: []string{"test"}, Transcript: io.Discard,
	})
	if err != nil || usage.Outcome != "success" {
		t.Fatalf("%s's stand-in backend did not complete: %v, usage %+v", name, err, usage)
	}
	filename, unit := "tool-timeout", time.Millisecond
	if name == "codex" {
		filename, unit = "args", time.Second
	}
	data, err := os.ReadFile(filepath.Join(dir, filename))
	if err != nil {
		t.Fatal(err)
	}
	value := strings.TrimSpace(string(data))
	if name == "codex" {
		matches := regexp.MustCompile(`(?:^|[ ,{])tool_timeout_sec=([0-9]+)(?:[, }]|$)`).FindAllStringSubmatch(value, -1)
		if len(matches) != 1 {
			t.Fatalf("expected one actual Codex MCP tool limit, found %d in %q", len(matches), value)
		}
		value = matches[0][1]
	}
	n, err := strconv.ParseInt(value, 10, 64)
	if err != nil || n <= 0 {
		t.Fatalf("%s emitted an invalid tool limit %q: %v", name, value, err)
	}
	return time.Duration(n) * unit
}

sources.internal/plumbing/sandbox_check_accept_t:
package plumbing

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// These checks use the operational API documented in
// sandbox_shards_accept_test.go. Check must distinguish a completed failing
// acceptance test from one that did not finish. Cancellation may be reported
// as an error or as a rejected Checked result; neither may approve the plan.

// A draft's test files are proposed additions, so they must be absent from the
// repository that Check copies. Keep their sources in the draft workspace.
func s397Draft(t *testing.T, f *s397Fixture) string {
	t.Helper()
	if err := f.plan.Validate(); err != nil {
		t.Fatal("invalid fixture plan: ", err)
	}
	ws := t.TempDir()
	draft := struct {
		Name    string   `json:"name"`
		Summary string   `json:"summary"`
		Files   []string `json:"files"`
		Tests   []Test   `json:"tests"`
	}{f.plan.Name, f.plan.Summary, f.plan.Files, f.plan.Tests}
	b, err := json.MarshalIndent(draft, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	s397Write(t, filepath.Join(ws, "plan.json"), string(b)+"\n", 0o644)
	for file, src := range f.plan.Sources {
		s397Write(t, filepath.Join(ws, "tests", filepath.FromSlash(file)), src, 0o644)
		if err := os.Remove(filepath.Join(f.root, filepath.FromSlash(file))); err != nil {
			t.Fatal(err)
		}
	}
	return ws
}

func s397Checker(f *s397Fixture, timeout time.Duration) Sandbox {
	return Sandbox{Image: "local-fixture", ModCache: f.mod, Cache: f.cache,
		Timeout: timeout, ShardTimeout: 30 * time.Second}
}

func TestSandboxAcceptanceResultsArePerTestWithinPackage(t *testing.T) {
	f := s397New(t)
	f.pkg(t, "mixed", "")
	f.accept(t, "mixed", "TestAlreadyPasses", `package mixed
import "testing"
func TestAlreadyPasses(t *testing.T) {}
func TestNeedsChange(t *testing.T) { t.Fatal("the proposed behavior is missing") }
`)
	f.plan.Tests = append(f.plan.Tests, Test{Name: "TestNeedsChange", File: "mixed/pinned_accept_test.go", Says: "The proposed behavior is present."})
	f.warm(t)
	r := f.run(t, 30*time.Second, 20*time.Second)
	for name, want := range map[string]bool{"TestAlreadyPasses": true, "TestNeedsChange": false} {
		key := "mixed/pinned_accept_test.go:" + name
		if got, found := r.Accepted[key]; !found || got != want {
			t.Errorf("Accepted[%q] = %v, present=%v, want %v; package failure must not overwrite another test's result", key, got, found, want)
		}
	}
	s397Status(t, r, "mixed", "TestAlreadyPasses", "accept", "passed")
	s397Status(t, r, "mixed", "TestNeedsChange", "accept", "failed")
	if r.Passed() {
		t.Error("one passing acceptance test hid the failing test in its package")
	}

	c, err := Check(context.Background(), s397Draft(t, f), f.root, s397Checker(f, 30*time.Second))
	if err != nil || c == nil {
		t.Fatalf("Check: result=%+v, error=%v", c, err)
	}
	s397Status(t, c.Run, "mixed", "TestAlreadyPasses", "accept", "passed")
	s397Status(t, c.Run, "mixed", "TestNeedsChange", "accept", "failed")
	if !c.Run.Accepted["mixed/pinned_accept_test.go:TestAlreadyPasses"] || c.Run.Accepted["mixed/pinned_accept_test.go:TestNeedsChange"] {
		t.Errorf("Check lost individual acceptance outcomes: %+v", c.Run.Accepted)
	}
	if c.Problem == "" || !strings.Contains(c.Problem, "TestAlreadyPasses") {
		t.Errorf("Check must reject and identify a test that already passes even when its neighbor fails: %q", c.Problem)
	}
}

// The same fixture can stop in vet, an ordinary test, or the acceptance replay.
// Observation files let cancellation happen after the intended phase starts.
func s397IncompleteFixture(t *testing.T, phase string) (*s397Fixture, string) {
	t.Helper()
	f := s397New(t)
	started := filepath.Join(f.observe, "phase-started")
	ordinarySource := fmt.Sprintf(`package pending
import ("os"; "testing"; "time")
func TestOrdinary(t *testing.T) {
  if %t {
    if err := os.WriteFile(%q, []byte("ordinary test started"), 0600); err != nil { t.Fatal(err) }
    time.Sleep(60*time.Second)
  }
}
`, phase == "test", started)
	if phase == "after_acceptance" {
		// Only one ordinary invocation may write the replay marker, even
		// when workers start different top-level tests in separate processes.
		ordinarySource = ""
	}
	f.pkg(t, "pending", ordinarySource)
	acceptSource := fmt.Sprintf(`package pending
import ("os"; "testing"; "time")
func TestNeedsChange(t *testing.T) {
  if %t {
    prior, err := os.ReadFile(%q)
    if err != nil && !os.IsNotExist(err) { t.Fatal(err) }
    if len(prior) > 0 {
      if err := os.WriteFile(%q, []byte("acceptance test started"), 0600); err != nil { t.Fatal(err) }
      time.Sleep(60*time.Second)
    }
    if err := os.WriteFile(%q, []byte("ordinary execution completed"), 0600); err != nil { t.Fatal(err) }
  }
  if %t {
    if err := os.WriteFile(%q, []byte("a completed failure"), 0600); err != nil { t.Fatal(err) }
  }
  t.Fatal("the proposed behavior is missing")
}
`, phase == "acceptance", filepath.Join(f.observe, "first-execution"), started, filepath.Join(f.observe, "first-execution"), phase == "after_acceptance", filepath.Join(f.observe, "completed-failure"))
	if phase == "after_acceptance" {
		acceptSource += fmt.Sprintf(`
func TestMain(m *testing.M) {
  before, _ := os.ReadFile(%q)
  code := m.Run()
  if len(before) > 0 {
    if err := os.WriteFile(%q, []byte("acceptance emitted its failure"), 0600); err != nil { panic(err) }
    time.Sleep(60*time.Second)
  }
  os.Exit(code)
}
`, filepath.Join(f.observe, "completed-failure"), started)
	}
	f.accept(t, "pending", "TestNeedsChange", acceptSource)
	f.warm(t)
	if phase == "vet" {
		t.Setenv("S397_HANG_VET", "1")
		started = filepath.Join(f.control, "vet-started")
	}
	return f, started
}

func TestSandboxCheckRejectsDeadlineEvidence(t *testing.T) {
	for _, phase := range []string{"vet", "test", "acceptance", "after_acceptance"} {
		t.Run(phase, func(t *testing.T) {
			f, started := s397IncompleteFixture(t, phase)
			ws := s397Draft(t, f)
			begin := time.Now()
			c, err := Check(context.Background(), ws, f.root, s397Checker(f, 8*time.Second))
			if err != nil || c == nil {
				t.Fatalf("the sandbox's own deadline must deliver its partial result: result=%+v, error=%v", c, err)
			}
			if elapsed := time.Since(begin); elapsed > 13*time.Second {
				t.Errorf("deadline check took %s, want at most 8s plus 5s cleanup", elapsed)
			}
			if _, err := os.Stat(started); err != nil {
				t.Fatalf("the intended %s phase never started: %v\n%s", phase, err, c.Run.Output)
			}
			if !c.Run.DeadlineExceeded || c.Run.Passed() {
				t.Errorf("deadline must remain a failed run: %+v", c.Run)
			}
			want := "not_run"
			if phase == "acceptance" {
				want = "running"
			} else if phase == "after_acceptance" {
				want = "failed"
			}
			s397Status(t, c.Run, "pending", "TestNeedsChange", "accept", want)
			if c.Problem == "" {
				t.Errorf("Check approved a plan using an acceptance test that was %s when %s hit the deadline", want, phase)
			}
		})
	}
	t.Run("context_cancellation", s397CheckRejectsInterruptedRun)
	t.Run("completed_failure_remains_eligible", s397CheckAllowsCompletedFailures)
}

func s397CheckRejectsInterruptedRun(t *testing.T) {
	for _, phase := range []string{"vet", "test", "acceptance", "after_acceptance"} {
		t.Run(phase, func(t *testing.T) {
			f, marker := s397IncompleteFixture(t, phase)
			ws := s397Draft(t, f)
			ctx, cancel := context.WithCancel(context.Background())
			defer cancel()
			started := make(chan bool, 1)
			go func() {
				ticker := time.NewTicker(10 * time.Millisecond)
				defer ticker.Stop()
				limit := time.NewTimer(20 * time.Second)
				defer limit.Stop()
				for {
					select {
					case <-ticker.C:
						if _, err := os.Stat(marker); err == nil {
							started <- true
							cancel()
							return
						}
					case <-limit.C:
						started <- false
						cancel()
						return
					case <-ctx.Done():
						started <- false
						return
					}
				}
			}()
			begin := time.Now()
			c, err := Check(ctx, ws, f.root, s397Checker(f, 30*time.Second))
			cancel()
			if !<-started {
				t.Fatalf("Check returned or setup expired before the %s phase could be interrupted: result=%+v, error=%v", phase, c, err)
			}
			if elapsed := time.Since(begin); elapsed > 25*time.Second {
				t.Errorf("cancelled check did not return promptly: %s", elapsed)
			}
			if err == nil && (c == nil || c.Problem == "") {
				t.Errorf("Check must fail closed after context cancellation during %s: result=%+v", phase, c)
			}
		})
	}
}

func TestSandboxCheckRejectsUnfinishedAcceptance(t *testing.T) {
	for _, status := range []string{"not_run", "running"} {
		t.Run(status, func(t *testing.T) {
			f := s397New(t)
			f.pkg(t, "unfinished", "")
			// The normal test-phase invocation fails completely. During the
			// acceptance replay, either TestMain omits m.Run or the test exits
			// the process before reporting a result. Neither is failure evidence.
			f.accept(t, "unfinished", "TestNeedsChange", fmt.Sprintf(`package unfinished
import ("os"; "testing")
const seen = %q
func TestMain(m *testing.M) {
  if %t { if _, err := os.Stat(seen); err == nil { os.Exit(0) } }
  os.Exit(m.Run())
}
func TestNeedsChange(t *testing.T) {
  if %t { if _, err := os.Stat(seen); err == nil { os.Exit(2) } }
  if err := os.WriteFile(seen, []byte("normal test completed"), 0600); err != nil { t.Fatal(err) }
  t.Fatal("the proposed behavior is missing")
}
`, filepath.Join(f.observe, "normal-test-finished"), status == "not_run", status == "running"))
			f.warm(t)
			c, err := Check(context.Background(), s397Draft(t, f), f.root, s397Checker(f, 30*time.Second))
			if err != nil || c == nil {
				t.Fatalf("Check should report the incomplete acceptance run: result=%+v, error=%v", c, err)
			}
			if c.Run.DeadlineExceeded {
				t.Fatal("this fixture exits on its own; it must exercise incomplete evidence independently of the outer deadline")
			}
			s397Status(t, c.Run, "unfinished", "TestNeedsChange", "test", "failed")
			s397Status(t, c.Run, "unfinished", "TestNeedsChange", "accept", status)
			if c.Problem == "" {
				t.Errorf("Check approved a plan whose acceptance test was %s, with no completed failing result", status)
			}
		})
	}
}

func s397CheckAllowsCompletedFailures(t *testing.T) {
	for _, ordinaryFails := range []bool{false, true} {
		t.Run(fmt.Sprintf("ordinary_failure_%t", ordinaryFails), func(t *testing.T) {
			f := s397New(t)
			f.pkg(t, "pending", fmt.Sprintf(`package pending
import "testing"
func TestOrdinary(t *testing.T) { if %t { t.Fatal("existing regression") } }
`, ordinaryFails))
			f.accept(t, "pending", "TestNeedsChange", `package pending
import "testing"
func TestNeedsChange(t *testing.T) { t.Fatal("the proposed behavior is missing") }
`)
			f.warm(t)
			c, err := Check(context.Background(), s397Draft(t, f), f.root, s397Checker(f, 30*time.Second))
			if err != nil || c == nil {
				t.Fatalf("Check: result=%+v, error=%v", c, err)
			}
			if c.Problem != "" {
				t.Errorf("a completed failing acceptance test must remain eligible: %s\n%s", c.Problem, c.Run.Output)
			}
			if c.Run.DeadlineExceeded || c.Run.Passed() || c.Run.Accepted["pending/pinned_accept_test.go:TestNeedsChange"] {
				t.Errorf("completed failure was misclassified: %+v", c.Run)
			}
			s397Status(t, c.Run, "pending", "TestNeedsChange", "accept", "failed")
			want := "passed"
			if ordinaryFails {
				want = "failed"
			}
			s397Status(t, c.Run, "pending", "TestOrdinary", "test", want)
		})
	}
	t.Run("new_api_does_not_build_yet", func(t *testing.T) {
		// Plans may introduce an API the original checkout cannot compile.
		// An observed compiler failure is conclusive evidence, distinct from
		// a deadline that prevented the compiler or acceptance test running.
		f := s397New(t)
		f.pkg(t, "pending", "")
		f.accept(t, "pending", "TestNeedsChange", `package pending
import "testing"
func TestNeedsChange(t *testing.T) { RequireNewAPI397() }
`)
		c, err := Check(context.Background(), s397Draft(t, f), f.root, s397Checker(f, 30*time.Second))
		if err != nil || c == nil {
			t.Fatalf("Check: result=%+v, error=%v", c, err)
		}
		if c.Problem != "" || c.Run.DeadlineExceeded || c.Run.Accepted["pending/pinned_accept_test.go:TestNeedsChange"] {
			t.Errorf("a completed compiler failure must remain eligible evidence for a new API: problem=%q result=%+v", c.Problem, c.Run)
		}
	})
}

sources.internal/plumbing/sandbox_phases_accept_:
package plumbing

import (
	"context"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"testing"
	"time"
)

// The host already stops Docker on its deadline. That cannot substitute for
// bounded waits inside the container: the runner must stop subprocesses and
// return its partial records while its output pipe is still available.
// This Docker stand-in copies the staged entry and runs it independently,
// with precisely the budget/environment Run supplied. Its CLI returns early,
// so the host's cancellation/removal cannot rescue an unbounded inner phase.
func TestSandboxBoundsEveryPhaseInsideContainer(t *testing.T) {
	for _, phase := range []string{"vet", "build", "discovery", "acceptance"} {
		t.Run(phase, func(t *testing.T) {
			f := s397New(t)
			started := filepath.Join(f.observe, "phase-started")
			f.pkg(t, "alpha", fmt.Sprintf(`package alpha
import ("os"; "strings"; "testing"; "time")
func TestMain(m *testing.M) {
  if %t {
    for _, arg := range os.Args[1:] {
      if arg == "-test.list" || strings.HasPrefix(arg, "-test.list=") {
        os.WriteFile(%q, nil, 0600)
        time.Sleep(60*time.Second)
      }
    }
  }
  os.Exit(m.Run())
}
func TestHealthy(t *testing.T) {}
`, phase == "discovery", started))
			f.accept(t, "contract", "TestRatified", fmt.Sprintf(`package contract
import ("os"; "testing"; "time")
func TestRatified(t *testing.T) {
  p := %q
  if %t { if _, err := os.Stat(p); err == nil { time.Sleep(60*time.Second) } }
  if err := os.WriteFile(p, []byte("first execution finished"), 0600); err != nil { t.Fatal(err) }
}
`, filepath.Join(f.observe, "contract-runs"), phase == "acceptance"))
			f.warm(t)
			if phase == "vet" || phase == "build" {
				verb := "vet"
				if phase == "build" {
					verb = "test"
				}
				s397Write(t, filepath.Join(f.bin, "go"), fmt.Sprintf(`#!/usr/bin/env python3
import os, pathlib, sys, time
a = sys.argv[1:]
if a and a[0] == "-C": a = a[2:]
elif a and a[0].startswith("-C="): a = a[1:]
if a and a[0] == %q:
    pathlib.Path(%q).write_text("started")
    time.sleep(60)
os.execv(os.environ["S397_REAL_GO"], [os.environ["S397_REAL_GO"]] + sys.argv[1:])
`, verb, started), 0o755)
			}
			s397Write(t, filepath.Join(f.bin, "docker"), s397DetachedDocker, 0o755)
			t.Cleanup(func() {
				// The watchdog also cleans up if an assertion fails before the
				// runner returns. All fixture bodies themselves have a 60s bound.
				exec.Command("python3", "-c", `import os, pathlib, signal, sys
try: os.killpg(int(pathlib.Path(sys.argv[1]).read_text()), signal.SIGKILL)
except (FileNotFoundError, ProcessLookupError): pass
`, filepath.Join(f.control, "detached-group")).Run()
			})
			const timeout = 6 * time.Second
			began := time.Now()
			s := Sandbox{Image: "detached-fixture", ModCache: f.mod, Cache: f.cache, Timeout: timeout, ShardTimeout: 30 * time.Second}
			// The intentionally detached CLI cannot give Run a complete result;
			// assess the actual entry's output after it exits, below.
			_, _ = s.Run(context.Background(), f.root, f.plan)
			var exit []byte
			for time.Since(began) < timeout+5*time.Second {
				if b, err := os.ReadFile(filepath.Join(f.control, "inner-exit")); err == nil && len(b) > 0 {
					exit = b
					break
				}
				time.Sleep(20 * time.Millisecond)
			}
			out, _ := os.ReadFile(filepath.Join(f.control, "inner-output"))
			if len(exit) == 0 {
				t.Fatalf("%s outlived the runner's %s budget without host cancellation:\n%s", phase, timeout, out)
			}
			if _, err := strconv.Atoi(string(exit)); err != nil {
				t.Fatalf("%s ended only through the fixture watchdog: %s\n%s", phase, exit, out)
			}
			r := parse(string(out), f.plan)
			if !r.DeadlineExceeded || r.Passed() {
				t.Errorf("the inner %s deadline must produce failed partial results: %+v\n%s", phase, r, out)
			}
			s397Summary(t, r, "deadline")
			if phase == "acceptance" {
				if !r.Vet || !r.Tests {
					t.Errorf("completed phases were lost: %s", r.Summary())
				}
				s397Status(t, r, "contract", "TestRatified", "accept", "running")
			} else if _, err := os.Stat(started); err != nil {
				t.Errorf("fixture never entered %s: %v\n%s", phase, err, out)
			}
			if r.Accepted["contract/pinned_accept_test.go:TestRatified"] {
				t.Error("unfinished acceptance phase must not count as accepted")
			}
		})
	}
}

const s397DetachedDocker = `#!/usr/bin/env python3
import os, pathlib, shutil, signal, subprocess, sys
control = pathlib.Path(os.environ["S397_CONTROL"])
a = sys.argv[1:]
if a and a[0] == "rm": sys.exit(0)
if not a or a[0] != "run" or a[-3:-1] != ["sh", "-c"]: sys.exit(2)
env, mounts = dict(os.environ), {}
i = 1
while i < len(a):
    if a[i] in ("-e", "--env"):
        k, _, v = a[i+1].partition("="); env[k] = v; i += 2
    elif a[i] in ("-v", "--volume"):
        p = a[i+1].split(":"); mounts[p[1]] = p[0]; i += 2
    else: i += 1
src = str(control / "independent-src")
shutil.copytree(mounts["/src"], src)
mounts["/src"] = src
for k, v in list(env.items()):
    if v in mounts: env[k] = mounts[v]
import shlex
script = a[-1].replace("cd /src", "cd " + shlex.quote(src))
pid = os.fork()
if pid:
    (control / "detached-group").write_text(str(pid))
    sys.exit(0)
os.setsid()
# Do not keep the fake CLI's output pipes open after it returns.
fd = os.open(control / "inner-output", os.O_CREAT | os.O_WRONLY | os.O_TRUNC, 0o600)
os.dup2(fd, 1); os.dup2(fd, 2); os.close(fd)
try:
    code = subprocess.run(["sh", "-c", script], cwd=src, env=env, timeout=15).returncode
    (control / "inner-exit").write_text(str(code))
except subprocess.TimeoutExpired:
    (control / "inner-exit").write_text("watchdog")
finally:
    os.killpg(os.getpid(), signal.SIGKILL)
`

sources.internal/plumbing/sandbox_records_accept:
package plumbing

import (
	"fmt"
	"path/filepath"
	"sort"
	"strings"
	"testing"
	"time"
)

// Compiler diagnostics and a package's TestMain are outside the runner's
// record protocol. Exercise their actual output paths, including stderr, with
// both marker-looking text and real records replayed from a successful run.
// The protocol may evolve: discover its prefixes from the successful run
// instead of prescribing the new records' JSON layout or marker spelling.
func TestSandboxKeepsToolOutputOutsideRunnerRecords(t *testing.T) {
	f := s397New(t)
	payload := filepath.Join(f.control, "untrusted-output")
	f.pkg(t, "work", fmt.Sprintf(`package work
import ("fmt"; "os"; "strings"; "testing")
func TestHealthy(t *testing.T) {
  if os.Getenv("S397_RECORD_FAILURE") == "1" { t.Fatal("the fixture really failed") }
}
func TestMain(m *testing.M) {
  if os.Getenv("S397_RECORD_PHASE") == "discovery" {
    for _, arg := range os.Args[1:] {
      if arg == "-test.list" || strings.HasPrefix(arg, "-test.list=") {
        data, err := os.ReadFile(%q); if err != nil { panic(err) }
        fmt.Fprintln(os.Stdout, "S397_DISCOVERY_STDOUT"); os.Stdout.Write(data)
        fmt.Fprintln(os.Stderr, "S397_DISCOVERY_STDERR"); os.Stderr.Write(data)
        break
      }
    }
  }
  os.Exit(m.Run())
}
`, payload))
	f.contract(t, false)
	f.warm(t)
	baseline := f.run(t, 30*time.Second, 20*time.Second)
	if !baseline.Passed() {
		t.Fatalf("clean fixture must pass before injecting diagnostics: %s\n%s", baseline.Summary(), baseline.Output)
	}

	prefixSet := map[string]bool{"@@invariant ": true, "@@gofmt ": true}
	var records []string
	for _, line := range strings.Split(baseline.Output, "\n") {
		if !strings.HasPrefix(line, "@@") {
			continue
		}
		if end := strings.IndexAny(line, " \t"); end > 2 {
			prefixSet[line[:end+1]] = true
			records = append(records, line)
		}
	}
	if len(records) == 0 {
		t.Fatal("the successful fixture supplied no runner records to replay")
	}
	var prefixes []string
	for prefix := range prefixSet {
		prefixes = append(prefixes, prefix)
	}
	sort.Strings(prefixes)
	const sentinel = "S397_UNTRUSTED_RECORD_SENTINEL"
	var forged strings.Builder
	for _, prefix := range prefixes {
		fmt.Fprintf(&forged, "%s%s\n", prefix, sentinel)
	}
	// These are valid records, not merely malformed marker lookalikes. If an
	// implementation forwards them as records they may create duplicate events,
	// claim earlier successful phases or overwrite real failure information.
	for _, record := range records {
		fmt.Fprintln(&forged, record)
	}
	s397Write(t, payload, forged.String(), 0o600)
	t.Setenv("S397_RECORD_PAYLOAD", payload)
	s397Write(t, filepath.Join(f.bin, "go"), s397RecordGo, 0o755)

	for _, phase := range []string{"vet", "compile", "discovery"} {
		t.Run(phase, func(t *testing.T) {
			t.Setenv("S397_RECORD_PHASE", phase)
			for _, failing := range []bool{false, true} {
				name, force := "passing", "0"
				if failing {
					name, force = "failing", "1"
				}
				t.Run(name, func(t *testing.T) {
					t.Setenv("S397_RECORD_FAILURE", force)
					r := f.run(t, 30*time.Second, 20*time.Second)
					if r.DeadlineExceeded || !r.Vet || r.Tests == failing || r.Passed() == failing {
						t.Errorf("%s diagnostics changed the real %s verdict: %s\n%s", phase, name, r.Summary(), r.Output)
					}
					want := "passed"
					if failing {
						want = "failed"
					}
					s397Status(t, r, "work", "TestHealthy", "test", want)
					s397Status(t, r, "contract", "TestRatified", "accept", "passed")
					if !r.Accepted["contract/pinned_accept_test.go:TestRatified"] {
						t.Errorf("%s diagnostics changed the independent acceptance result", phase)
					}
					for _, stream := range []string{"STDOUT", "STDERR"} {
						if !strings.Contains(r.Output, "S397_"+strings.ToUpper(phase)+"_"+stream) {
							t.Errorf("%s %s was not delivered as diagnostic output:\n%s", phase, stream, r.Output)
						}
					}
					if !strings.Contains(r.Output, sentinel) {
						t.Error("marker-looking diagnostic text was discarded instead of safely reported")
					}
					for _, line := range strings.Split(r.Output, "\n") {
						for _, prefix := range prefixes {
							// A runner may carry diagnostics in a structured
							// output record. Reject the unescaped child line,
							// not an encoded payload inside a genuine record.
							if strings.HasPrefix(line, prefix+sentinel) {
								t.Errorf("%s diagnostic escaped as a runner record: %q", phase, line)
							}
						}
					}
				})
			}
		})
	}
}

// Only add output around the real Go command. Discovery output comes from the
// fixture's actual compiled TestMain, so it also tests reuse of that binary.
const s397RecordGo = `#!/usr/bin/env python3
import os, pathlib, sys
args = sys.argv[1:]
command = args
if command and command[0] == "-C": command = command[2:]
elif command and command[0].startswith("-C="): command = command[1:]
phase = os.environ.get("S397_RECORD_PHASE")
inject = bool(command) and ((phase == "vet" and command[0] == "vet") or
                           (phase == "compile" and command[0] == "test" and
                            any(arg in ("-c", "-c=true") for arg in command[1:])))
if inject:
    data = pathlib.Path(os.environ["S397_RECORD_PAYLOAD"]).read_bytes()
    for stream, label in ((sys.stdout.buffer, "STDOUT"), (sys.stderr.buffer, "STDERR")):
        stream.write(("S397_" + phase.upper() + "_" + label + "\n").encode())
        stream.write(data)
        stream.flush()
real = os.environ["S397_REAL_GO"]
os.execv(real, [real] + args)
`

sources.internal/plumbing/sandbox_shards_accept_:
package plumbing

import (
	"context"
	"encoding/json"
	"fmt"
	"go/format"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"testing"
	"time"
)

// The operational API added by #397 is deliberately small:
//
// Sandbox.Timeout and Sandbox.ShardTimeout are time.Duration overrides which
// can shorten, but never extend, the production limits (zero uses the default).
// Timeout covers the entire Run, starting before checkout preparation.
// ShardTimeout bounds the whole shared-queue test phase, starting when its
// eight workers start; it does not restart for each test they pull. Every
// invocation is bounded by the time left in that phase and in the whole run.
// Result.DeadlineExceeded identifies the sandbox's own deadline. That deadline
// returns a failed Result, nil, so the existing test tool delivers the report.
// Result.TestResults contains records with Package (Go import path), Name
// (including subtest suffixes), Phase ("test" or "accept"), Status ("passed",
// "failed", "skipped", "running", or "not_run"), and Shard (1..8 in the test
// phase). A shard timeout may leave its interrupted test "running" while the
// shard is reported as failed. Results are keyed by phase, package and name.
// Summary preserves failure/deadline identities even when Output is tailed.
//
// These tests execute the real sandbox entry script and real Go fixture tests.
// Only Docker is replaced, by a local process-group boundary. They require
// neither Docker nor a network and never execute repository code on the host
// outside the same boundary already used for ordinary Go unit tests.

type s397Fixture struct {
	root, observe, control, cache, mod, bin, realGo string
	plan                                            *Plan
}

func s397Write(t *testing.T, name, text string, mode os.FileMode) {
	t.Helper()
	if err := os.MkdirAll(filepath.Dir(name), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(name, []byte(text), mode); err != nil {
		t.Fatal(err)
	}
}

func s397New(t *testing.T) *s397Fixture {
	t.Helper()
	if runtime.GOOS == "windows" {
		t.Skip("the sandbox and its local Docker stand-in use POSIX processes")
	}
	if _, err := exec.LookPath("python3"); err != nil {
		t.Fatal("the pinned sandbox runner and this fixture need python3: ", err)
	}
	goBin, err := exec.LookPath("go")
	if err != nil {
		t.Fatal(err)
	}
	cache := os.Getenv("GOCACHE")
	if cache == "" || cache == "off" {
		out, err := exec.Command(goBin, "env", "GOCACHE").Output()
		if err != nil {
			t.Fatal(err)
		}
		cache = strings.TrimSpace(string(out))
	}
	// Every fixture is a separate build: reuse compiler objects, but not the
	// elapsed-time history that may reorder another fixture's test queue.
	cache = s397IsolatedCache(t, cache)
	f := &s397Fixture{root: t.TempDir(), observe: t.TempDir(), control: t.TempDir(),
		cache: cache, mod: t.TempDir(), bin: t.TempDir(), realGo: goBin,
		plan: &Plan{Name: "shard fixture", Summary: "Run every fixture test and report its result.", Sources: map[string]string{}}}
	s397Write(t, filepath.Join(f.root, "go.mod"), "module example.com/shards397\n\ngo 1.27.1\n", 0o644)
	s397Write(t, filepath.Join(f.bin, "docker"), s397Docker, 0o755)
	s397Write(t, filepath.Join(f.bin, "go"), s397Go, 0o755)
	t.Setenv("S397_CONTROL", f.control)
	t.Setenv("S397_REAL_GO", f.realGo)
	t.Setenv("PATH", f.bin+string(os.PathListSeparator)+os.Getenv("PATH"))
	return f
}

func (f *s397Fixture) pkg(t *testing.T, dir, tests string) {
	t.Helper()
	s397Write(t, filepath.Join(f.root, dir, "code.go"), "package "+dir+"\n", 0o644)
	f.plan.Files = append(f.plan.Files, dir+"/code.go")
	if tests != "" {
		formatted, err := format.Source([]byte(tests))
		if err != nil {
			t.Fatal(err)
		}
		s397Write(t, filepath.Join(f.root, dir, "code_test.go"), string(formatted), 0o644)
	}
}

func (f *s397Fixture) accept(t *testing.T, dir, name, body string) {
	t.Helper()
	file := dir + "/pinned_accept_test.go"
	formatted, err := format.Source([]byte(body))
	if err != nil {
		t.Fatal(err)
	}
	body = string(formatted)
	s397Write(t, filepath.Join(f.root, file), body, 0o644)
	f.plan.Tests = append(f.plan.Tests, Test{Name: name, File: file, Says: "The fixture's pinned check passes."})
	f.plan.Sources[file] = body
}

func (f *s397Fixture) contract(t *testing.T, blockSecond bool) {
	t.Helper()
	f.accept(t, "contract", "TestRatified", fmt.Sprintf(`package contract
import ("os"; "strings"; "testing"; "time")
func TestRatified(t *testing.T) {
  p := %q
  before, _ := os.ReadFile(p)
  out, err := os.OpenFile(p, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0600)
  if err != nil { t.Fatal(err) }; if _, err = out.WriteString("run\n"); err != nil { t.Fatal(err) }; out.Close()
  if %t && strings.Count(string(before), "run\n") > 0 { for { time.Sleep(time.Second) } }
}
`, filepath.Join(f.observe, "contract-runs"), blockSecond))
}

// Audit real compiler invocations and real test processes. TestMain records
// discovery as well as execution, so rebuilding for go test -list or for the
// acceptance phase cannot hide behind a warm Go build cache. Relative testdata
// also makes executing a compiled binary from the package directory observable.
func (f *s397Fixture) audit(t *testing.T, pkgs ...string) {
	t.Helper()
	s397Write(t, filepath.Join(f.control, "audit"), "enabled", 0o644)
	for _, pkg := range pkgs {
		src := fmt.Sprintf(`package %s
import ("crypto/sha256"; "encoding/hex"; "encoding/json"; "fmt"; "io"; "os"; "path/filepath"; "strings"; "testing")
func TestMain(m *testing.M) {
  if os.Getenv("S397_AUDIT") == "1" {
    fail := func(err error) { fmt.Fprintln(os.Stderr, err); os.Exit(2) }
    data, err := os.ReadFile("testdata/package.txt"); if err != nil { fail(err) }
    if string(data) != %q { fail(fmt.Errorf("test binary ran outside its package directory")) }
    exe, err := os.Executable(); if err != nil { fail(err) }
    binary, err := os.Open(exe); if err != nil { fail(err) }
    hash := sha256.New(); if _, err := io.Copy(hash, binary); err != nil { fail(err) }; binary.Close()
    phase := "run"
    for _, arg := range os.Args[1:] { if arg == "-test.list" || strings.HasPrefix(arg, "-test.list=") { phase = "list" } }
    event, err := json.Marshal(map[string]string{"kind": "binary", "package": %q, "phase": phase, "executable": exe, "digest": hex.EncodeToString(hash.Sum(nil))}); if err != nil { fail(err) }
    log, err := os.OpenFile(filepath.Join(os.Getenv("S397_CONTROL"), "events.jsonl"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0600); if err != nil { fail(err) }
    if _, err := log.Write(append(event, '\n')); err != nil { fail(err) }; log.Close()
  }
  os.Exit(m.Run())
}
`, pkg, pkg, "example.com/shards397/"+pkg)
		formatted, err := format.Source([]byte(src))
		if err != nil {
			t.Fatal(err)
		}
		s397Write(t, filepath.Join(f.root, pkg, "audit_test.go"), string(formatted), 0o644)
		s397Write(t, filepath.Join(f.root, pkg, "testdata", "package.txt"), pkg, 0o644)
	}
}

func (f *s397Fixture) assertBuiltOnce(t *testing.T, pkgs ...string) {
	t.Helper()
	log, err := os.Open(filepath.Join(f.control, "events.jsonl"))
	if err != nil {
		t.Fatal("missing real build and binary observations: ", err)
	}
	defer log.Close()
	type event struct {
		Kind        string   `json:"kind"`
		ID          int      `json:"id"`
		Packages    []string `json:"packages"`
		CompileOnly bool     `json:"compile_only"`
		Code        int      `json:"code"`
		Package     string   `json:"package"`
		Phase       string   `json:"phase"`
		Executable  string   `json:"executable"`
		Digest      string   `json:"digest"`
	}
	builds, completed := map[string]int{}, map[string]bool{}
	active := map[int]bool{}
	binaries := map[string]event{}
	started := false
	decoder := json.NewDecoder(log)
	for {
		var got event
		if err := decoder.Decode(&got); err == io.EOF {
			break
		} else if err != nil {
			t.Fatal("build observation: ", err)
		}
		switch got.Kind {
		case "build_start":
			if len(active) != 0 {
				t.Errorf("package compilations overlapped: %v started with %v still active", got.Packages, active)
			}
			if started {
				t.Errorf("compilation began after test execution started: %v", got.Packages)
			}
			if !got.CompileOnly {
				t.Errorf("go test compiled and executed %v instead of preparing reusable test binaries", got.Packages)
			}
			active[got.ID] = true
			for _, pkg := range got.Packages {
				builds[pkg]++
			}
		case "build_done":
			if !active[got.ID] || got.Code != 0 {
				t.Errorf("compilation did not finish successfully: %+v", got)
			}
			delete(active, got.ID)
			for _, pkg := range got.Packages {
				completed[pkg] = got.Code == 0
			}
		case "binary":
			if !completed[got.Package] {
				t.Errorf("%s binary ran before its compilation finished", got.Package)
			}
			if got.Phase == "run" {
				started = true
				if len(active) != 0 {
					t.Errorf("%s test execution overlapped compilation", got.Package)
				}
				for _, pkg := range pkgs {
					if !completed["example.com/shards397/"+pkg] {
						t.Errorf("%s tests ran before %s's binary was built", got.Package, pkg)
					}
				}
			}
			if prior, ok := binaries[got.Package]; ok && (prior.Executable != got.Executable || prior.Digest != got.Digest) {
				t.Errorf("%s did not reuse the same binary for discovery, shards and acceptance: %+v then %+v", got.Package, prior, got)
			}
			binaries[got.Package] = got
		default:
			t.Errorf("unknown build observation: %+v", got)
		}
	}
	if !started || len(active) != 0 {
		t.Errorf("incomplete build/run observations: tests started=%v, active builds=%v", started, active)
	}
	for pkg, count := range builds {
		if count != 1 {
			t.Errorf("%s compiled %d times, want once across discovery, shards and acceptance", pkg, count)
		}
	}
	for _, pkg := range pkgs {
		name := "example.com/shards397/" + pkg
		if builds[name] != 1 || !completed[name] || binaries[name].Executable == "" {
			t.Errorf("%s must build one reusable test binary: builds=%d, completed=%v, binary=%+v", name, builds[name], completed[name], binaries[name])
		}
	}
}

// Warm compilation outside the measured short fixture deadline, using the
// same cache and flags the sandbox uses. This runs no test bodies.
func (f *s397Fixture) warm(t *testing.T, pkgs ...string) {
	t.Helper()
	if len(pkgs) == 0 {
		pkgs = []string{"./..."}
	}
	ctx, cancel := context.WithTimeout(context.Background(), 90*time.Second)
	defer cancel()
	args := append([]string{"test", "-run", "^$", "-count=1", "-vet=off"}, pkgs...)
	cmd := exec.CommandContext(ctx, f.realGo, args...)
	cmd.Dir = f.root
	cmd.Env = append(os.Environ(), "GOCACHE="+f.cache, "GOMODCACHE="+f.mod, "GOTOOLCHAIN=local", "GOPROXY=off", "CGO_ENABLED=0", "GOFLAGS=-mod=readonly -p=1", "GOMAXPROCS=2")
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("compile fixture: %v\n%s", err, out)
	}
}

func (f *s397Fixture) run(t *testing.T, timeout, shardTimeout time.Duration) Result {
	t.Helper()
	s := Sandbox{Image: "local-fixture", ModCache: f.mod, Cache: f.cache, Timeout: timeout, ShardTimeout: shardTimeout}
	start := time.Now()
	r, err := s.Run(context.Background(), f.root, f.plan)
	if err != nil {
		t.Fatalf("Sandbox.Run must deliver a check result: %v\n%s", err, r.Output)
	}
	if elapsed := time.Since(start); elapsed > timeout+5*time.Second {
		t.Fatalf("fixture deadline %s returned after %s", timeout, elapsed)
	}
	return r
}

func s397Status(t *testing.T, r Result, pkg, name, phase, want string) int {
	t.Helper()
	found, shard := 0, 0
	for _, got := range r.TestResults {
		if got.Package == "example.com/shards397/"+pkg && got.Name == name && got.Phase == phase {
			found++
			shard = got.Shard
			if got.Status != want {
				t.Errorf("%s %s/%s: status %q, want %q", phase, pkg, name, got.Status, want)
			}
		}
	}
	if found != 1 {
		t.Fatalf("%s %s/%s has %d final records, want one; records: %+v\n%s", phase, pkg, name, found, r.TestResults, r.Output)
	}
	return shard
}

func s397Summary(t *testing.T, r Result, words ...string) {
	t.Helper()
	summary := strings.ToLower(r.Summary())
	for _, word := range words {
		if !strings.Contains(summary, strings.ToLower(word)) {
			t.Errorf("the delivered summary lacks %q:\n%s", word, r.Summary())
		}
	}
}

func TestSandboxShardsEveryTopLevelTestExactlyOnce(t *testing.T) {
	f := s397New(t)
	var src strings.Builder
	fmt.Fprintf(&src, `package alpha
import ("fmt"; "os"; "path/filepath"; "strconv"; "testing"; "time")
func visit(name string) {
  dir := %q
  out, err := os.OpenFile(filepath.Join(dir, "alpha-"+name), os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600)
  if err != nil { panic(err) }; fmt.Fprint(out, os.Getpid()); out.Close()
  if err := os.WriteFile(filepath.Join(dir, "worker-"+strconv.Itoa(os.Getpid())), nil, 0600); err != nil { panic(err) }
  deadline := time.Now().Add(20*time.Second)
  for { workers, _ := filepath.Glob(filepath.Join(dir, "worker-*")); if len(workers) >= 8 { break }; if time.Now().After(deadline) { panic("eight test shards never ran together") }; time.Sleep(10*time.Millisecond) }
}
func Example() { visit("Example"); fmt.Println("hello")
// Output: hello
}
func FuzzSeed(f *testing.F) { f.Add(1); f.Fuzz(func(t *testing.T, n int) { visit("FuzzSeed") }) }
func TestChildren(t *testing.T) { visit("TestChildren"); t.Run("first", func(t *testing.T) { visit("child-first") }); t.Run("second", func(t *testing.T) { visit("child-second") }) }
`, f.observe)
	alpha := []string{"Example", "FuzzSeed", "TestChildren", "TestNewlyAdded"}
	for i := 0; i < 16; i++ {
		name := fmt.Sprintf("TestCase%02d", i)
		alpha = append(alpha, name)
		fmt.Fprintf(&src, "func %s(t *testing.T) { visit(%q) }\n", name, name)
	}
	src.WriteString("func TestNewlyAdded(t *testing.T) { visit(\"TestNewlyAdded\") }\n")
	f.pkg(t, "alpha", src.String())
	f.pkg(t, "beta", fmt.Sprintf(`package beta
import ("fmt"; "os"; "path/filepath"; "testing")
func record(t *testing.T, name string) { p := filepath.Join(%q, "beta-"+name); f, err := os.OpenFile(p, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600); if err != nil { t.Fatal(err) }; fmt.Fprint(f, os.Getpid()); f.Close() }
func TestCase00(t *testing.T) { record(t, "TestCase00") }
func TestCase01(t *testing.T) { record(t, "TestCase01") }
`, f.observe))
	f.pkg(t, "empty", "")
	f.contract(t, false)
	f.audit(t, "alpha", "beta", "contract")
	f.warm(t)
	r := f.run(t, 60*time.Second, 40*time.Second)
	if !r.Passed() {
		t.Fatalf("fixture failed: %s\n%s", r.Summary(), r.Output)
	}
	f.assertBuiltOnce(t, "alpha", "beta", "contract")
	sort.Strings(alpha)
	all := append([]string(nil), alpha...)
	all = append(all, "beta:TestCase00", "beta:TestCase01", "contract:TestRatified")
	workers := map[int]bool{}
	processes := map[string]bool{}
	for _, entry := range all {
		pkg, name := "alpha", entry
		if p := strings.SplitN(entry, ":", 2); len(p) == 2 {
			pkg, name = p[0], p[1]
		}
		shard := s397Status(t, r, pkg, name, "test", "passed")
		if shard < 1 || shard > 8 {
			t.Errorf("%s/%s has worker %d, want one of eight queue workers", pkg, name, shard)
		}
		workers[shard] = true
		if pkg == "contract" {
			continue
		}
		pid, err := os.ReadFile(filepath.Join(f.observe, pkg+"-"+name))
		if err != nil {
			t.Fatal(err)
		}
		if n, err := strconv.Atoi(string(pid)); err != nil || n <= 0 {
			t.Fatalf("%s/%s did not record a real process ID: %q", pkg, name, pid)
		}
		if processes[string(pid)] {
			t.Errorf("top-level test %s/%s reused another test's process %s", pkg, name, pid)
		}
		processes[string(pid)] = true
	}
	if len(workers) != 8 {
		t.Errorf("ran with %d workers, want eight concurrent queue workers", len(workers))
	}
	for _, name := range []string{"first", "second"} {
		s397Status(t, r, "alpha", "TestChildren/"+name, "test", "passed")
		if _, err := os.Stat(filepath.Join(f.observe, "alpha-child-"+name)); err != nil {
			t.Fatal(err)
		}
	}
	s397Status(t, r, "contract", "TestRatified", "accept", "passed")
	count, err := os.ReadFile(filepath.Join(f.observe, "contract-runs"))
	if err != nil || string(count) != "run\nrun\n" {
		t.Errorf("acceptance runs = %q, %v; want once in a shard and once in the pinned acceptance phase", count, err)
	}
	var args []string
	b, err := os.ReadFile(filepath.Join(f.control, "args.json"))
	if err != nil || json.Unmarshal(b, &args) != nil {
		t.Fatalf("Docker argument record: %s, %v", b, err)
	}
	for key, value := range map[string]string{"--memory": "4g", "--pids-limit": "1024", "--network": "none", "--hostname": "localhost"} {
		found := false
		for i := 0; i+1 < len(args); i++ {
			found = found || (args[i] == key && args[i+1] == value)
		}
		if !found {
			t.Errorf("container arguments %q lack %s %s", args, key, value)
		}
	}
	env := map[string]string{}
	for i := 0; i+1 < len(args); i++ {
		if args[i] == "-e" || args[i] == "--env" {
			key, value, _ := strings.Cut(args[i+1], "=")
			env[key] = value
		}
	}
	if env["GOMAXPROCS"] != "2" {
		t.Errorf("container GOMAXPROCS = %q, want 2", env["GOMAXPROCS"])
	}
	for _, flag := range []string{"-mod=readonly", "-p=1"} {
		found := false
		for _, got := range strings.Fields(env["GOFLAGS"]) {
			found = found || got == flag
		}
		if !found {
			t.Errorf("container GOFLAGS = %q, missing %s", env["GOFLAGS"], flag)
		}
	}
}

func TestSandboxNamesFailuresFromEveryShard(t *testing.T) {
	for _, kind := range []string{"early_failure", "failure", "panic", "shard_timeout", "build_error"} {
		t.Run(kind, func(t *testing.T) {
			f := s397New(t)
			f.pkg(t, "good", "package good\nimport \"testing\"\nfunc TestHealthy(t *testing.T) {}\n")
			body := "t.Fatal(\"fixture failure\")"
			imports := "\"testing\""
			if kind == "panic" {
				body = "panic(\"fixture panic\")"
			}
			if kind == "shard_timeout" {
				body, imports = "time.Sleep(60*time.Second)", "\"testing\"; \"time\""
			}
			var src strings.Builder
			fmt.Fprintf(&src, "package bad\nimport (%s)\n", imports)
			if kind != "build_error" && kind != "early_failure" {
				// A test late in discovery must fail the run just as an early one does.
				for i := 0; i < 7; i++ {
					fmt.Fprintf(&src, "func TestA%02d(t *testing.T) {}\n", i)
				}
			}
			fmt.Fprintf(&src, "func TestBroken(t *testing.T) { %s }\n", body)
			f.pkg(t, "bad", src.String())
			f.contract(t, false)
			if kind == "build_error" {
				s397Write(t, filepath.Join(f.root, "bad", "code.go"), "package bad\nvar Broken = missingSymbol397\n", 0o644)
				f.warm(t, "./good", "./contract")
			} else {
				f.warm(t)
			}
			shardTimeout := 20 * time.Second
			if kind == "shard_timeout" {
				shardTimeout = time.Second
			}
			r := f.run(t, 35*time.Second, shardTimeout)
			if r.Passed() || r.Tests || r.DeadlineExceeded {
				t.Errorf("%s: Passed=%v Tests=%v DeadlineExceeded=%v\n%s", kind, r.Passed(), r.Tests, r.DeadlineExceeded, r.Output)
			}
			s397Status(t, r, "good", "TestHealthy", "test", "passed")
			if !r.Accepted["contract/pinned_accept_test.go:TestRatified"] {
				t.Errorf("a failed shard prevented independent acceptance checks: %s", r.Output)
			}
			s397Summary(t, r, "bad")
			if kind != "build_error" {
				s397Summary(t, r, "TestBroken", "shard")
			}
			switch kind {
			case "early_failure", "failure":
				if shard := s397Status(t, r, "bad", "TestBroken", "test", "failed"); shard < 1 || shard > 8 {
					t.Errorf("failed test belongs to worker %d, want one of eight queue workers", shard)
				}
			case "shard_timeout":
				summary := strings.ToLower(r.Summary())
				if !strings.Contains(summary, "timeout") && !strings.Contains(summary, "timed out") {
					t.Errorf("summary must identify the shard timeout: %s", r.Summary())
				}
			case "build_error":
				s397Summary(t, r, "build")
			}
		})
	}
}

// A fixed round-robin strands Test08Release behind Test00Busy. A shared
// queue lets any free worker run it, while the busy worker is still waiting.
// This checks balancing without assuming a worker ID or racing elapsed times.
func TestSandboxWorkersPullFromSharedQueue(t *testing.T) {
	f := s397New(t)
	var src strings.Builder
	fmt.Fprintf(&src, `package alpha
import ("os"; "path/filepath"; "testing"; "time")
var observations = %q
func Test00Busy(t *testing.T) {
  os.WriteFile(filepath.Join(observations, "busy"), nil, 0600)
  until := time.Now().Add(10*time.Second)
  for {
    if _, err := os.Stat(filepath.Join(observations, "released")); err == nil { return }
    if time.Now().After(until) { t.Fatal("queued work was stranded behind a busy worker") }
    time.Sleep(10*time.Millisecond)
  }
}
`, f.observe)
	for i := 1; i <= 7; i++ {
		fmt.Fprintf(&src, "func Test%02dQuick(t *testing.T) {}\n", i)
	}
	src.WriteString(`func Test08Release(t *testing.T) {
  until := time.Now().Add(10*time.Second)
  for {
    if _, err := os.Stat(filepath.Join(observations, "busy")); err == nil { break }
    if time.Now().After(until) { t.Fatal("busy test never started") }
    time.Sleep(10*time.Millisecond)
  }
  if err := os.WriteFile(filepath.Join(observations, "released"), nil, 0600); err != nil { t.Fatal(err) }
}
`)
	f.pkg(t, "alpha", src.String())
	f.contract(t, false)
	f.warm(t)
	r := f.run(t, 35*time.Second, 20*time.Second)
	if !r.Passed() {
		t.Fatalf("a free worker must take the next test while another worker is busy:\n%s\n%s", r.Summary(), r.Output)
	}
	busy := s397Status(t, r, "alpha", "Test00Busy", "test", "passed")
	release := s397Status(t, r, "alpha", "Test08Release", "test", "passed")
	if busy == release {
		t.Errorf("waiting test and its queued release both used worker %d", busy)
	}
}

func TestSandboxQueueBudgetDoesNotRestartPerTest(t *testing.T) {
	f := s397New(t)
	var src strings.Builder
	src.WriteString("package alpha\nimport (\"testing\"; \"time\")\n")
	for i := 0; i < 128; i++ {
		fmt.Fprintf(&src, "func TestWork%03d(t *testing.T) { time.Sleep(200*time.Millisecond) }\n", i)
	}
	f.pkg(t, "alpha", src.String())
	f.contract(t, false)
	f.warm(t)
	r := f.run(t, 30*time.Second, time.Second)
	if r.Passed() || r.Tests || r.DeadlineExceeded {
		t.Fatalf("the shared one-second test budget must expire before the whole-run deadline: %+v\n%s", r, r.Output)
	}
	passed, pending := 0, 0
	for _, result := range r.TestResults {
		if result.Package == "example.com/shards397/alpha" && result.Phase == "test" {
			if result.Status == "passed" {
				passed++
			}
			if result.Status == "not_run" {
				pending++
			}
		}
	}
	if passed == 0 || pending == 0 {
		t.Errorf("want completed and unstarted tests after the shared budget expires; passed=%d pending=%d", passed, pending)
	}
	if !r.Accepted["contract/pinned_accept_test.go:TestRatified"] {
		t.Errorf("the touched-test phase used up the acceptance phase's remaining whole-run budget:\n%s", r.Output)
	}
	summary := strings.ToLower(r.Summary())
	if !strings.Contains(summary, "timeout") && !strings.Contains(summary, "timed out") {
		t.Errorf("the summary must identify the touched-test phase timeout: %s", r.Summary())
	}
}

func TestSandboxDeadlineReturnsPartialResults(t *testing.T) {
	for _, phase := range []string{"tests", "vet", "acceptance"} {
		t.Run(phase, func(t *testing.T) {
			f := s397New(t)
			var src strings.Builder
			fmt.Fprintf(&src, `package work
import ("os"; "testing"; "time")
func Test00Passed(t *testing.T) {}
func Test01Failed(t *testing.T) { if %t { t.Fatal("before deadline") } }
func Test02Running(t *testing.T) { if %t { for { os.WriteFile(%q, []byte(time.Now().String()), 0600); time.Sleep(30*time.Millisecond) } } }
`, phase == "tests", phase == "tests", filepath.Join(f.observe, "heartbeat"))
			for i := 3; i <= 9; i++ {
				fmt.Fprintf(&src, "func Test%02dRunning(t *testing.T) { if %t { for { time.Sleep(time.Second) } } }\n", i, phase == "tests")
			}
			src.WriteString("func Test10Queued(t *testing.T) {}\n")
			f.pkg(t, "work", src.String())
			f.contract(t, phase == "acceptance")
			f.warm(t)
			if phase == "vet" {
				t.Setenv("S397_HANG_VET", "1")
			}
			r := f.run(t, 8*time.Second, 30*time.Second)
			if !r.DeadlineExceeded || r.Passed() {
				t.Fatalf("deadline must return a failed partial result: %+v\n%s", r, r.Output)
			}
			s397Summary(t, r, "deadline")
			if r.Accepted["contract/pinned_accept_test.go:TestRatified"] {
				t.Error("a test which passed in a shard cannot satisfy an unfinished acceptance phase")
			}
			if _, err := os.Stat(filepath.Join(f.control, "removed")); err != nil {
				t.Fatal("the timed-out container was not removed: ", err)
			}
			switch phase {
			case "tests":
				s397Status(t, r, "work", "Test00Passed", "test", "passed")
				s397Status(t, r, "work", "Test01Failed", "test", "failed")
				s397Status(t, r, "work", "Test02Running", "test", "running")
				s397Status(t, r, "work", "Test10Queued", "test", "not_run")
				s397Summary(t, r, "work", "Test00Passed", "passed", "Test01Failed", "failed", "Test02Running", "running", "Test10Queued")
				before, err := os.ReadFile(filepath.Join(f.observe, "heartbeat"))
				if err != nil {
					t.Fatal("hanging fixture never started: ", err)
				}
				time.Sleep(150 * time.Millisecond)
				after, _ := os.ReadFile(filepath.Join(f.observe, "heartbeat"))
				if string(before) != string(after) {
					t.Error("a fixture process kept running after the sandbox returned")
				}
			case "vet":
				if r.Vet {
					t.Error("vet never finished")
				}
				s397Summary(t, r, "vet")
			case "acceptance":
				if !r.Tests || !r.Vet {
					t.Errorf("completed checks were lost: %s", r.Output)
				}
				s397Status(t, r, "contract", "TestRatified", "accept", "running")
				s397Summary(t, r, "accept", "contract", "TestRatified", "running")
			}
		})
	}
}

func TestSandboxKeepsAcceptanceResultsByPackage(t *testing.T) {
	f := s397New(t)
	for _, pkg := range []string{"left", "right"} {
		f.pkg(t, pkg, "")
		body := ""
		if pkg == "right" {
			body = "t.Fatal(\"right failed\")"
		}
		f.accept(t, pkg, "TestSameName", "package "+pkg+"\nimport \"testing\"\nfunc TestSameName(t *testing.T) { "+body+" }\n")
	}
	f.warm(t)
	r := f.run(t, 30*time.Second, 20*time.Second)
	if r.Passed() || !r.Accepted["left/pinned_accept_test.go:TestSameName"] || r.Accepted["right/pinned_accept_test.go:TestSameName"] {
		t.Fatalf("package-qualified acceptance results: %+v\n%s", r.Accepted, r.Output)
	}
	s397Status(t, r, "left", "TestSameName", "accept", "passed")
	s397Status(t, r, "right", "TestSameName", "accept", "failed")
	s397Summary(t, r, "right", "TestSameName")
}

// Every go test invocation compiles a package, even when Go can reuse cached
// compiler output. Record its semantic package targets and completion around
// the real command; accept either flag spelling and package patterns, without
// depending on how the sandbox formats its shell script.
const s397Go = `#!/usr/bin/env python3
import json, os, pathlib, subprocess, sys
a = sys.argv[1:]
real = os.environ["S397_REAL_GO"]
control = pathlib.Path(os.environ["S397_CONTROL"])
prefix = []
if a and a[0] == "-C":
    prefix, a = a[:2], a[2:]
elif a and a[0].startswith("-C="):
    prefix, a = a[:1], a[1:]
if a and a[0] == "vet" and os.environ.get("S397_HANG_VET") == "1":
    (control / "vet-started").write_text("started")
    os.execvp("sleep", ["sleep", "60"])
if not a or a[0] != "test" or os.environ.get("S397_AUDIT") != "1":
    os.execv(real, [real] + sys.argv[1:])
value_flags = {
    "-o", "-p", "-run", "-list", "-timeout", "-count", "-parallel", "-cpu", "-shuffle",
    "-vet", "-exec", "-bench", "-benchtime", "-fuzz", "-fuzztime", "-fuzzminimizetime",
    "-asmflags", "-gcflags", "-ldflags", "-gccgoflags", "-tags", "-mod", "-modfile",
    "-overlay", "-pkgdir", "-toolexec", "-buildmode", "-compiler", "-covermode",
    "-coverpkg", "-coverprofile", "-blockprofile", "-blockprofilerate", "-cpuprofile",
    "-memprofile", "-memprofilerate", "-mutexprofile", "-mutexprofilefraction",
    "-outputdir", "-trace"
}
patterns, compile_only, i = [], False, 1
while i < len(a):
    arg = a[i]
    if arg == "-args": break
    if arg.startswith("-"):
        flag, equal, value = arg.partition("=")
        if flag == "-c": compile_only = not equal or value == "true"
        i += 2 if flag in value_flags and not equal else 1
    else:
        patterns.append(arg); i += 1
listed = subprocess.run([real] + prefix + ["list", "-f", "{{.ImportPath}}"] + patterns,
                        stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
if listed.returncode:
    sys.stderr.write(listed.stderr); sys.exit(listed.returncode)
packages = listed.stdout.split()
def record(kind, **extra):
    event = dict(kind=kind, id=os.getpid(), packages=packages, **extra)
    fd = os.open(control / "events.jsonl", os.O_CREAT | os.O_APPEND | os.O_WRONLY, 0o600)
    try: os.write(fd, (json.dumps(event) + "\n").encode())
    finally: os.close(fd)
record("build_start", compile_only=compile_only)
code = subprocess.run([real] + sys.argv[1:]).returncode
record("build_done", code=code)
sys.exit(code if code >= 0 else 128-code)
`

// The stand-in honors the existing sh -c entry contract, real environment and
// mounts, and Docker's important cancellation property: rm kills every process
// belonging to the container. It never supplies fabricated test output.
const s397Docker = `#!/usr/bin/env python3
import json, os, pathlib, signal, subprocess, sys
a = sys.argv[1:]
control = pathlib.Path(os.environ["S397_CONTROL"])
if a and a[0] == "rm":
    (control / "removed").write_text(" ".join(a))
    try:
        os.killpg(int((control / "group").read_text()), signal.SIGKILL)
    except (ProcessLookupError, FileNotFoundError):
        pass
    sys.exit(0)
if not a or a[0] != "run":
    sys.exit(2)
(control / "args.json").write_text(json.dumps(a))
env = dict(os.environ)
if (control / "audit").exists(): env["S397_AUDIT"] = "1"
mounts = {}
i = 1
while i < len(a):
    if a[i] in ("-e", "--env"):
        k, _, v = a[i+1].partition("="); env[k] = v; i += 2
    elif a[i] in ("-v", "--volume"):
        parts = a[i+1].split(":"); mounts[parts[1]] = parts[0]; i += 2
    else:
        i += 1
if a[-3:-1] != ["sh", "-c"]:
    sys.exit("sandbox lost its sh -c entry contract")
src = mounts["/src"]
for k, v in list(env.items()):
    if v in mounts: env[k] = mounts[v]
# Paths are shell quoted because the copied checkout may have spaces.
import shlex
script = a[-1].replace("cd /src", "cd " + shlex.quote(src))
p = subprocess.Popen(["sh", "-c", script], cwd=src, env=env, start_new_session=True)
(control / "group").write_text(str(p.pid))
try:
    code = p.wait()
finally:
    try: os.killpg(p.pid, signal.SIGKILL)
    except ProcessLookupError: pass
sys.exit(code if code >= 0 else 128-code)
`

sources.internal/plumbing/sandbox_timings_accept:
package plumbing

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
	"time"
)

// The timing hint's persistence contract is deliberately separate from result
// records: $GOCACHE/invariant-test-times-v1.json contains a JSON array of
// {"package": GoImportPath, "name": TopLevelName, "elapsed_seconds": Number}.
// Only finite, nonnegative elapsed times for discovered top-level tests are
// usable. Unusable data is ignored. The file is an ordering hint, never the
// source of the test inventory, executable commands, or pass/fail evidence.
const s397TimingFile = "invariant-test-times-v1.json"

type s397Timing struct {
	Package string  `json:"package"`
	Name    string  `json:"name"`
	Elapsed float64 `json:"elapsed_seconds"`
}

// Go's cache entries live in 256 hexadecimal buckets. Share only those
// buckets with the warmed host cache, so each fixture owns its timing hint.
// Copying the whole cache is expensive; giving every fixture a cold standard
// library would make the short deadline checks measure compilation instead.
func s397IsolatedCache(t *testing.T, existing string) string {
	t.Helper()
	cache := t.TempDir()
	for n := 0; n < 256; n++ {
		bucket := fmt.Sprintf("%02x", n)
		source := filepath.Join(existing, bucket)
		info, err := os.Stat(source)
		if os.IsNotExist(err) {
			continue
		}
		if err != nil {
			t.Fatal(err)
		}
		if !info.IsDir() {
			t.Fatalf("Go cache bucket %s is not a directory", source)
		}
		if err := os.Symlink(source, filepath.Join(cache, bucket)); err != nil {
			t.Fatal(err)
		}
	}
	return cache
}

func s397SeedTimings(t *testing.T, f *s397Fixture, records []s397Timing) {
	t.Helper()
	data, err := json.Marshal(records)
	if err != nil {
		t.Fatal(err)
	}
	s397Write(t, filepath.Join(f.cache, s397TimingFile), string(data), 0o600)
}

// Seven new, unknown tests occupy seven workers. All remaining test bodies
// then execute through the eighth worker, making their relative order visible
// without assuming that eight simultaneous OS process starts are ordered.
// These blockers sort before every observed package and are never recorded in
// the seeded cache. The last observed test releases them.
func s397TimingBlockers(t *testing.T, f *s397Fixture) {
	t.Helper()
	var src strings.Builder
	fmt.Fprintf(&src, `package ahead
import ("os"; "path/filepath"; "testing"; "time")
func hold(t *testing.T, name string) {
  dir := %q
  if err := os.WriteFile(filepath.Join(dir, name), nil, 0600); err != nil { t.Fatal(err) }
  until := time.Now().Add(15*time.Second)
  for {
    if _, err := os.Stat(filepath.Join(dir, "timing-release")); err == nil { return }
    if time.Now().After(until) { t.Fatal("ordered queue did not reach the release test") }
    time.Sleep(5*time.Millisecond)
  }
}
`, f.observe)
	for n := 0; n < 7; n++ {
		fmt.Fprintf(&src, "func TestHold%02d(t *testing.T) { hold(t, %q) }\n", n, fmt.Sprintf("timing-holder-%02d", n))
	}
	f.pkg(t, "ahead", src.String())
}

// Measured bodies sleep only during the learning run. During the ordered run
// they wait until all seven blocker bodies have started, append a single
// observation, and optionally release the blockers. Thus the observations
// represent execution, not a scheduler's self-reported intended ordering.
func s397TimingSource(f *s397Fixture, pkg string) string {
	return fmt.Sprintf(`package %s
import ("fmt"; "os"; "path/filepath"; "testing"; "time")
func sample(t *testing.T, elapsed time.Duration, release bool) {
  if os.Getenv("S397_TIMING_MODE") == "learn" { time.Sleep(elapsed); return }
  dir := %q
  until := time.Now().Add(10*time.Second)
  for {
    ready := true
    for n := 0; n < 7; n++ {
      if _, err := os.Stat(filepath.Join(dir, fmt.Sprintf("timing-holder-%%02d", n))); err != nil { ready = false }
    }
    if ready { break }
    if time.Now().After(until) { t.Fatal("unknown blocker tests were not queued first") }
    time.Sleep(5*time.Millisecond)
  }
  out, err := os.OpenFile(filepath.Join(dir, "timing-order"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0600)
  if err != nil { t.Fatal(err) }
  _, err = out.WriteString(%q + "/" + t.Name() + "\n"); out.Close()
  if err != nil { t.Fatal(err) }
  if release {
    if err := os.WriteFile(filepath.Join(dir, "timing-release"), nil, 0600); err != nil { t.Fatal(err) }
  }
}
`, pkg, f.observe, pkg)
}

func s397TimingOrder(t *testing.T, f *s397Fixture, r Result, want []string) {
	t.Helper()
	if !r.Passed() {
		t.Fatalf("ordered fixture failed: %s\n%s", r.Summary(), r.Output)
	}
	data, err := os.ReadFile(filepath.Join(f.observe, "timing-order"))
	if err != nil {
		t.Fatal(err)
	}
	if got := strings.Fields(string(data)); !reflect.DeepEqual(got, want) {
		t.Errorf("observed execution order = %v, want %v", got, want)
	}
	for _, entry := range want {
		pkg, name, _ := strings.Cut(entry, "/")
		s397Status(t, r, pkg, name, "test", "passed")
	}
	for n := 0; n < 7; n++ {
		s397Status(t, r, "ahead", fmt.Sprintf("TestHold%02d", n), "test", "passed")
	}
}

func TestSandboxReusesMeasuredTimesInSharedCache(t *testing.T) {
	f := s397New(t)
	f.pkg(t, "measured", s397TimingSource(f, "measured")+`
func TestAFast(t *testing.T) { sample(t, 10*time.Millisecond, true) }
func TestBMedium(t *testing.T) { sample(t, 300*time.Millisecond, false) }
func TestZSlowest(t *testing.T) { sample(t, 900*time.Millisecond, false) }
`)
	f.contract(t, false)
	f.warm(t)
	t.Setenv("S397_TIMING_MODE", "learn")
	first := f.run(t, 35*time.Second, 20*time.Second)
	if !first.Passed() {
		t.Fatalf("learning run failed: %s\n%s", first.Summary(), first.Output)
	}
	data, err := os.ReadFile(filepath.Join(f.cache, s397TimingFile))
	if err != nil {
		t.Fatal("the first run did not persist elapsed times in its supplied build cache: ", err)
	}
	var saved []s397Timing
	if err := json.Unmarshal(data, &saved); err != nil {
		t.Fatal("the first run wrote invalid timing records: ", err)
	}
	times := map[string]float64{}
	for _, record := range saved {
		if record.Package == "example.com/shards397/measured" {
			if _, duplicate := times[record.Name]; duplicate {
				t.Errorf("the first run wrote duplicate timing records for %s", record.Name)
			}
			times[record.Name] = record.Elapsed
		}
	}
	fast, hasFast := times["TestAFast"]
	medium, hasMedium := times["TestBMedium"]
	slow, hasSlow := times["TestZSlowest"]
	if !hasFast || !hasMedium || !hasSlow || !(0 <= fast && fast < medium && medium < slow) {
		t.Fatalf("the first run must record the measured top-level durations: %v", times)
	}

	// New tests remain unknown even though the other tests share a warm cache.
	// They hold seven workers; the measured slowest must get the remaining
	// worker before either shorter measured test, despite sorting last by name.
	s397TimingBlockers(t, f)
	f.warm(t, "./ahead")
	t.Setenv("S397_TIMING_MODE", "ordered")
	second := f.run(t, 35*time.Second, 20*time.Second)
	s397TimingOrder(t, f, second, []string{
		"measured/TestZSlowest", "measured/TestBMedium", "measured/TestAFast",
	})
}

func TestSandboxQueuesUnknownBeforeLongestKnownTests(t *testing.T) {
	f := s397New(t)
	s397TimingBlockers(t, f)
	f.pkg(t, "alpha", s397TimingSource(f, "alpha")+`
func TestZUnknown(t *testing.T) { sample(t, 0, false) }
func TestAKnownFast(t *testing.T) { sample(t, 0, true) }
func TestAUnknown(t *testing.T) { sample(t, 0, false) }
`)
	f.pkg(t, "beta", s397TimingSource(f, "beta")+`
func TestAKnownMiddle(t *testing.T) { sample(t, 0, false) }
func TestAUnknown(t *testing.T) { sample(t, 0, false) }
func TestZKnownSlow(t *testing.T) { sample(t, 0, false) }
`)
	f.contract(t, false)
	f.warm(t)
	// Neither file order nor package/name order matches elapsed-time order.
	// Contract's known zero keeps its acceptance fixture out of the unknowns.
	s397SeedTimings(t, f, []s397Timing{
		{"example.com/shards397/alpha", "TestAKnownFast", 1},
		{"example.com/shards397/beta", "TestAKnownMiddle", 20},
		{"example.com/shards397/contract", "TestRatified", 0},
		{"example.com/shards397/beta", "TestZKnownSlow", 90},
	})
	t.Setenv("S397_TIMING_MODE", "ordered")
	r := f.run(t, 35*time.Second, 20*time.Second)
	s397TimingOrder(t, f, r, []string{
		"alpha/TestAUnknown", "alpha/TestZUnknown", "beta/TestAUnknown",
		"beta/TestZKnownSlow", "beta/TestAKnownMiddle", "alpha/TestAKnownFast",
	})
}

func TestSandboxTimingHintsCannotChangeInventoryOrVerdicts(t *testing.T) {
	f := s397New(t)
	visit := func(pkg string) string {
		return fmt.Sprintf(`package %s
import ("os"; "testing")
func visit(t *testing.T, mayFail bool) {
  out, err := os.OpenFile(%q, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0600)
  if err != nil { t.Fatal(err) }
  _, err = out.WriteString(%q + "/" + t.Name() + "\n"); out.Close()
  if err != nil { t.Fatal(err) }
  if mayFail && os.Getenv("S397_TIMING_FAIL") == "1" { t.Fatal("real test-body failure") }
}
`, pkg, filepath.Join(f.observe, "timing-visits"), pkg)
	}
	f.pkg(t, "alpha", visit("alpha")+`
func TestSameName(t *testing.T) { visit(t, true) }
func TestMissingFromCache(t *testing.T) { visit(t, false) }
`)
	f.pkg(t, "beta", visit("beta")+`
func TestSameName(t *testing.T) { visit(t, false) }
`)
	f.pkg(t, "contract", "")
	f.accept(t, "contract", "TestPassing", visit("contract")+`
func TestPassing(t *testing.T) { visit(t, false) }
func TestConditionalFailure(t *testing.T) { visit(t, true) }
`)
	f.plan.Tests = append(f.plan.Tests, Test{Name: "TestConditionalFailure", File: "contract/pinned_accept_test.go", Says: "The fixture's conditional acceptance check passes."})
	f.warm(t)

	marker := filepath.Join(f.observe, "injected-command")
	quotedMarker, err := json.Marshal("TestSameName; touch " + marker + "; #")
	if err != nil {
		t.Fatal(err)
	}
	attacks := []struct{ name, data string }{
		{"truncated", `[{"package":"example.com/shards397/alpha","name":"TestSameName","elapsed_seconds":`},
		{"wrong_shape", `{"passed":true,"tests":[],"accepted":{"contract/pinned_accept_test.go:TestConditionalFailure":true}}`},
		{"invalid_values", `[
  null, [], "ignore me",
  {"package":17,"name":false,"elapsed_seconds":1},
  {"package":"example.com/shards397/alpha","name":"TestSameName","elapsed_seconds":-1},
  {"package":"example.com/shards397/alpha","name":"TestMissingFromCache","elapsed_seconds":1e999},
  {"package":"example.com/shards397/beta","name":"TestSameName","elapsed_seconds":"NaN"},
  {"package":"example.com/shards397/contract","name":"TestConditionalFailure","elapsed_seconds":null}
]`},
		{"hostile_inventory_and_results", fmt.Sprintf(`[
  {"package":"example.com/shards397/alpha","name":"TestSameName","elapsed_seconds":100,"status":"passed","passed":true,"skip":true},
  {"package":"example.com/shards397/alpha","name":"TestSameName","elapsed_seconds":200},
  {"package":"example.com/shards397/beta","name":"TestSameName","elapsed_seconds":1,"status":"failed"},
  {"package":"example.com/shards397/contract","name":"TestPassing","elapsed_seconds":9,"accepted":false},
  {"package":"example.com/shards397/contract","name":"TestConditionalFailure","elapsed_seconds":8,"accepted":true,"status":"passed"},
  {"package":"example.com/shards397/alpha","name":"TestInjected","elapsed_seconds":999},
  {"package":"../../outside","name":"TestSameName","elapsed_seconds":999},
  {"package":"example.com/shards397/alpha","name":%s,"elapsed_seconds":999},
  {"package":"example.com/shards397/alpha","name":"TestSameName/injected-child","elapsed_seconds":999}
]`, quotedMarker)},
	}
	for _, attack := range attacks {
		t.Run(attack.name, func(t *testing.T) {
			for _, fail := range []bool{false, true} {
				t.Run(fmt.Sprintf("failing_%t", fail), func(t *testing.T) {
					s397Write(t, filepath.Join(f.cache, s397TimingFile), attack.data, 0o600)
					s397Write(t, filepath.Join(f.observe, "timing-visits"), "", 0o600)
					t.Setenv("S397_TIMING_FAIL", "0")
					if fail {
						t.Setenv("S397_TIMING_FAIL", "1")
					}
					r := f.run(t, 35*time.Second, 20*time.Second)
					if r.DeadlineExceeded || !r.Vet || r.Tests == fail || r.Passed() == fail {
						t.Errorf("timing hint changed the actual verdict: %s\n%s", r.Summary(), r.Output)
					}
					want := map[string]int{
						"alpha/TestSameName": 1, "alpha/TestMissingFromCache": 1,
						"beta/TestSameName": 1, "contract/TestPassing": 2,
						"contract/TestConditionalFailure": 2,
					}
					data, err := os.ReadFile(filepath.Join(f.observe, "timing-visits"))
					if err != nil {
						t.Fatal(err)
					}
					seen := map[string]int{}
					for _, entry := range strings.Fields(string(data)) {
						seen[entry]++
					}
					if !reflect.DeepEqual(seen, want) {
						t.Errorf("hint removed, duplicated or injected test execution: got %v, want %v", seen, want)
					}
					results := 0
					for _, got := range r.TestResults {
						pkg := strings.TrimPrefix(got.Package, "example.com/shards397/")
						if _, known := want[pkg+"/"+got.Name]; !known || (got.Phase != "test" && (got.Phase != "accept" || pkg != "contract")) {
							t.Errorf("hint injected result evidence: %+v", got)
						}
						results++
					}
					if results != 7 {
						t.Errorf("got %d final test records, want five ordinary and two acceptance records", results)
					}
					if len(r.Accepted) != 2 {
						t.Errorf("hint changed the acceptance inventory: %+v", r.Accepted)
					}
					for entry, runs := range want {
						pkg, name, _ := strings.Cut(entry, "/")
						status := "passed"
						if fail && (entry == "alpha/TestSameName" || entry == "contract/TestConditionalFailure") {
							status = "failed"
						}
						s397Status(t, r, pkg, name, "test", status)
						if runs == 2 {
							s397Status(t, r, pkg, name, "accept", status)
							key := "contract/pinned_accept_test.go:" + name
							accepted, present := r.Accepted[key]
							if !present || accepted != (status == "passed") {
								t.Errorf("hint changed acceptance evidence %s: accepted=%v, present=%v", key, accepted, present)
							}
						}
					}
					if _, err := os.Stat(marker); !os.IsNotExist(err) {
						t.Errorf("a timing record executed a command: marker error=%v", err)
					}
				})
			}
		})
	}
}
